def solve(inputs: dict) -> float:
    s = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = int(inputs['K'])

    for _ in range(k):
        s = (a * s + b) % m

    return float(s)

